// UtterAI download / thank-you page.
//
// Everything shown here is derived from the release itself: the live GitHub API
// when it answers, and the committed snapshot in checksums.json (regenerated by
// CI from the release's own checksums.txt) when it doesn't. No file name, size
// or hash is ever hard-coded on this page.
const REPO = "thisisankit27/utter-ai";
const RELEASES = `https://github.com/${REPO}/releases/latest`;

/* ---------------------------------------------------------------- nav ---- */
const nav = document.querySelector("header.nav");
if (nav) {
  const onScroll = () => nav.classList.toggle("scrolled", window.scrollY > 8);
  onScroll();
  addEventListener("scroll", onScroll, { passive: true });
}
const navToggle = document.getElementById("nav-toggle");
const navLinks = document.getElementById("nav-links");
if (navToggle && navLinks) {
  const setMenu = (open) => {
    navLinks.classList.toggle("open", open);
    navToggle.setAttribute("aria-expanded", String(open));
  };
  navToggle.addEventListener("click", () =>
    setMenu(navToggle.getAttribute("aria-expanded") !== "true"),
  );
  navLinks.addEventListener("click", (e) => {
    if (e.target.tagName === "A") setMenu(false);
  });
}

/* ------------------------------------------------------------ variants ---- */
const VARIANTS = {
  windows: {
    label: "Windows installer",
    platform: "Windows 10 or 11, 64-bit",
    match: /-setup\.exe$/i,
    icon: '<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M3 5.5 10 4.5v7H3zM11 4.3 21 3v8.5H11zM3 12.5h7v7L3 18.5zM11 12.5h10V21l-10-1.3z"/></svg>',
    steps: [
      "<b>Open the downloaded <code>.exe</code>.</b> It installs just for you, so it never asks for an administrator password.",
      "<b>Windows may warn you.</b> UtterAI isn't code-signed yet, so SmartScreen shows \"Windows protected your PC\". Click <b>More info</b> → <b>Run anyway</b>. The checksum below is there if you'd like to confirm the file first.",
      "<b>Follow the installer.</b> It takes a few seconds and adds UtterAI to the Start menu.",
      "<b>Launch UtterAI</b> from the Start menu.",
    ],
    verify: (name) =>
      `# PowerShell\nGet-FileHash -Algorithm SHA256 .\\${name}`,
  },
  msi: {
    label: "Windows MSI package",
    platform: "Windows 10 or 11, 64-bit · for managed deployments",
    match: /\.msi$/i,
    icon: '<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M3 5.5 10 4.5v7H3zM11 4.3 21 3v8.5H11zM3 12.5h7v7L3 18.5zM11 12.5h10V21l-10-1.3z"/></svg>',
    steps: [
      "<b>Open the <code>.msi</code></b>, or deploy it with your usual tooling (<code>msiexec /i UtterAI_*.msi /qn</code>).",
      "<b>It installs machine-wide</b> and will ask for administrator rights.",
      "<b>Launch UtterAI</b> from the Start menu.",
      "For a normal single-machine install the <code>.exe</code> is the easier choice — it updates itself in place without a password.",
    ],
    verify: (name) => `# PowerShell\nGet-FileHash -Algorithm SHA256 .\\${name}`,
  },
  deb: {
    label: "Debian / Ubuntu package",
    platform: "Debian, Ubuntu and derivatives, 64-bit",
    match: /\.deb$/i,
    icon: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><path d="M9 21c1-3 1-6 0-9-.7-2 .3-4 3-4s3.7 3 3 6c-.5 2-.5 5 0 7" stroke-linecap="round"/></svg>',
    steps: [
      "<b>Install it:</b> <code>sudo apt install ./UtterAI_*_amd64.deb</code> — using <code>apt</code> rather than <code>dpkg</code> pulls in the media codecs UtterAI recommends for audio preview.",
      "<b>Launch it</b> from your applications menu, or run <code>UtterAI</code>.",
      "<b>Updating:</b> in-app updates on Debian and Ubuntu install through your package manager and will ask for your password. You can also just download the newer <code>.deb</code>.",
    ],
    verify: (name) => `sha256sum ${name}`,
  },
  appimage: {
    label: "Linux AppImage",
    platform: "Any 64-bit Linux · nothing to install",
    match: /\.AppImage$/i,
    icon: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><path d="M9 21c1-3 1-6 0-9-.7-2 .3-4 3-4s3.7 3 3 6c-.5 2-.5 5 0 7" stroke-linecap="round"/></svg>',
    steps: [
      "<b>Make it executable:</b> <code>chmod +x UtterAI_*.AppImage</code>",
      "<b>Run it:</b> <code>./UtterAI_*.AppImage</code> — there's nothing to install and nothing left behind.",
      "<b>It carries its own media codecs</b>, so audio preview works even on a minimal system.",
      "<b>Updating:</b> UtterAI replaces its own AppImage in place, so keep it somewhere you can write to.",
    ],
    verify: (name) => `sha256sum ${name}`,
  },
};

function detect() {
  const asked = new URLSearchParams(location.search).get("p");
  if (asked && VARIANTS[asked]) return asked;
  const ua = navigator.userAgent + " " + (navigator.platform || "");
  if (/Win/i.test(ua)) return "windows";
  if (/Ubuntu|Debian/i.test(ua)) return "deb";
  return "appimage";
}

/* ---------------------------------------------------------------- data ---- */
const $ = (id) => document.getElementById(id);
const fmtSize = (b) => (b ? (b / 1048576).toFixed(0) + " MB" : "");

/** Live release first (always current), committed snapshot as the fallback. */
async function loadRelease() {
  try {
    const r = await fetch(`https://api.github.com/repos/${REPO}/releases/latest`);
    if (!r.ok) throw new Error(String(r.status));
    const rel = await r.json();
    const live = {
      version: (rel.tag_name || "").replace(/^v/, ""),
      files: (rel.assets || []).map((a) => ({
        name: a.name,
        size: a.size,
        url: a.browser_download_url,
      })),
    };
    // The API doesn't carry hashes; merge them in from the snapshot.
    const snap = await loadSnapshot();
    if (snap && snap.version === live.version) {
      for (const f of live.files) {
        const s = snap.files.find((x) => x.name === f.name);
        if (s) f.sha256 = s.sha256;
      }
    }
    return live;
  } catch {
    const snap = await loadSnapshot();
    if (!snap) return null;
    return {
      version: snap.version,
      files: snap.files.map((f) => ({
        ...f,
        url: `https://github.com/${REPO}/releases/download/${snap.tag}/${f.name}`,
      })),
    };
  }
}

let snapshotPromise;
function loadSnapshot() {
  snapshotPromise ??= fetch("checksums.json", { cache: "no-cache" })
    .then((r) => (r.ok ? r.json() : null))
    .catch(() => null);
  return snapshotPromise;
}

/**
 * Kick off the download through a hidden iframe rather than by setting
 * `location.href`. The response is an attachment either way, so the browser
 * saves it and the page stays put — but if the URL ever fails (offline, a
 * pulled asset), a top-level navigation would replace this page with the
 * browser's error page and take the install instructions with it.
 */
function startDownload(url) {
  const frame = document.createElement("iframe");
  frame.hidden = true;
  frame.setAttribute("aria-hidden", "true");
  frame.src = url;
  document.body.appendChild(frame);
  setTimeout(() => frame.remove(), 120_000);
}

/* --------------------------------------------------------------- render --- */
let release = null;
let started = false;

function render(key, { autostart }) {
  const v = VARIANTS[key];
  const asset = release?.files.find((f) => v.match.test(f.name));

  $("dl-os-icon").innerHTML = v.icon;
  $("install-steps").innerHTML = v.steps.map((s) => `<li>${s}</li>`).join("");

  if (!asset) {
    // Never invent a file name or a hash. Say what we know and point at the
    // releases page, which always works.
    $("dl-name").textContent = v.label;
    $("dl-meta").textContent =
      "We couldn't reach GitHub to confirm the latest build — the button below always has it.";
    $("dl-again").href = RELEASES;
    $("dl-again").textContent = "Go to downloads";
    $("dl-lede").textContent =
      "Pick your file from the releases page and come back here for the setup steps.";
    $("verify").hidden = true;
    return;
  }

  $("dl-name").textContent = asset.name;
  $("dl-meta").textContent = [v.platform, fmtSize(asset.size)]
    .filter(Boolean)
    .join(" · ");
  $("dl-again").href = asset.url;
  $("dl-again").textContent = started ? "Download again" : "Download";
  $("all-hashes").href = RELEASES;

  if (asset.sha256) {
    $("verify").hidden = false;
    $("hash-file").textContent = `SHA-256 · ${asset.name}`;
    $("hash-value").textContent = asset.sha256;
    $("verify-cmd").textContent = v.verify(asset.name);
  } else {
    $("verify").hidden = true;
  }

  if (autostart && !started) {
    started = true;
    $("dl-eyebrow").textContent = "Download started";
    $("dl-lede").textContent = `UtterAI ${release.version} for ${v.label.toLowerCase()} should be downloading now. If nothing happened, use the button below.`;
    $("dl-again").textContent = "Download again";
    setTimeout(() => startDownload(asset.url), 700);
  } else if (!autostart) {
    $("dl-eyebrow").textContent = "Ready when you are";
    $("dl-lede").textContent = `UtterAI ${release.version} — ${v.platform}.`;
  }
}

/* ----------------------------------------------------------------- init --- */
(async function init() {
  let key = detect();
  release = await loadRelease();
  render(key, { autostart: true });

  document.querySelectorAll("[data-os]").forEach((a) => {
    a.addEventListener("click", (e) => {
      e.preventDefault();
      key = a.dataset.os;
      started = false;
      history.replaceState(null, "", `?p=${key}`);
      render(key, { autostart: false });
      document.querySelectorAll("[data-os]").forEach((x) =>
        x.classList.toggle("is-current", x === a),
      );
      $("dl-file").scrollIntoView({ block: "nearest", behavior: "smooth" });
    });
  });

  const copy = $("hash-copy");
  copy?.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText($("hash-value").textContent.trim());
      copy.textContent = "Copied";
      setTimeout(() => (copy.textContent = "Copy"), 1600);
    } catch {
      copy.textContent = "Select it manually";
      setTimeout(() => (copy.textContent = "Copy"), 2200);
    }
  });
})();
